import React, { useState, useEffect } from 'react';
import { Search } from 'lucide-react';

const AirtableStore = () => {
  const [products, setProducts] = useState([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState(null);
  const [searchTerm, setSearchTerm] = useState('');

  // ⚠️ IMPORTANT: Replace these with your actual Airtable credentials
  const AIRTABLE_API_KEY = 'patBxMl5uxbqMh90l.d0fa8c39cd2baed95b4d5f47cfa963e3374a2fbe8999edc690dc7a35bc6d8feb';
  const AIRTABLE_BASE_ID = 'appRMrTPEDmjy6Zka';
  const AIRTABLE_TABLE_NAME = 'Inventory';

  useEffect(() => {
    fetchProducts();
  }, []);

  const fetchProducts = async () => {
    try {
      const response = await fetch(
        `https://api.airtable.com/v0/${AIRTABLE_BASE_ID}/${AIRTABLE_TABLE_NAME}`,
        {
          headers: {
            Authorization: `Bearer ${AIRTABLE_API_KEY}`,
          },
        }
      );

      if (!response.ok) {
        throw new Error('Failed to fetch products');
      }

      const data = await response.json();

      const formattedProducts = data.records.map(record => ({
        id: record.id,
        name: record.fields.Name || record.fields.name || 'Unnamed Product',
        price: parseFloat(record.fields.Price || record.fields.price || 0),
        description: record.fields.Description || record.fields.description || '',
        image: record.fields.Image?.[0]?.url || record.fields.image?.[0]?.url || 'https://via.placeholder.com/400x400?text=No+Image',
        category: record.fields.Category || record.fields.category || 'Uncategorized',
      }));

      setProducts(formattedProducts);
      setLoading(false);
    } catch (err) {
      setError(err.message);
      setLoading(false);
    }
  };

  const filteredProducts = products.filter(product =>
    product.name.toLowerCase().includes(searchTerm.toLowerCase()) ||
    product.description.toLowerCase().includes(searchTerm.toLowerCase()) ||
    product.category.toLowerCase().includes(searchTerm.toLowerCase())
  );

  if (loading) {
    return (
      <div className="min-h-screen bg-gradient-to-br from-blue-50 via-white to-orange-50 flex items-center justify-center">
        <div className="text-center">
          <div className="animate-spin rounded-full h-16 w-16 border-b-4 border-blue-600 mx-auto"></div>
          <p className="mt-4 text-gray-700 text-lg font-medium">Loading products...</p>
        </div>
      </div>
    );
  }

  if (error) {
    return (
      <div className="min-h-screen bg-gradient-to-br from-red-50 to-orange-50 flex items-center justify-center p-4">
        <div className="bg-white rounded-3xl shadow-2xl p-8 max-w-md border-4 border-red-200">
          <div className="text-red-500 text-6xl mb-4">⚠️</div>
          <h2 className="text-2xl font-bold text-gray-800 mb-2">Configuration Error</h2>
          <p className="text-gray-600 mb-4">{error}</p>
          <p className="text-sm text-gray-500">Please update your Airtable credentials in the code.</p>
        </div>
      </div>
    );
  }

  return (
    <div className="min-h-screen bg-gradient-to-br from-blue-50 via-white to-orange-50">
      {/* Header */}
      <header className="bg-white shadow-lg border-b-4 border-yellow-400">
        <div className="max-w-7xl mx-auto px-4 py-8 sm:px-6 lg:px-8">
          <div className="flex justify-center">
            <img 
              src="/images/logo.png" 
              alt="UnrealPrices Logo" 
              className="h-32 w-32 object-contain"
              onError={(e) => {
                e.target.style.display = 'none';
                e.target.nextSibling.style.display = 'block';
              }}
            />
            <h1 className="text-4xl font-bold text-gray-800 text-center" style={{display: 'none'}}>
              Unreal<span className="text-blue-600">Prices</span>
            </h1>
          </div>
        </div>
      </header>

      {/* Search Bar */}
      <div className="max-w-7xl mx-auto px-4 py-8 sm:px-6 lg:px-8">
        <div className="relative max-w-2xl mx-auto">
          <Search className="absolute left-5 top-1/2 transform -translate-y-1/2 text-blue-400" size={22} />
          <input
            type="text"
            placeholder="Search for amazing deals..."
            value={searchTerm}
            onChange={(e) => setSearchTerm(e.target.value)}
            className="w-full pl-14 pr-4 py-4 rounded-full border-3 border-blue-200 focus:border-blue-500 focus:outline-none shadow-md hover:shadow-lg transition-all duration-200 text-lg"
          />
        </div>
      </div>

      {/* Products Grid */}
      <main className="max-w-7xl mx-auto px-4 pb-16 sm:px-6 lg:px-8">
        {filteredProducts.length === 0 ? (
          <div className="text-center py-16">
            <p className="text-gray-500 text-xl">No products found</p>
          </div>
        ) : (
          <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-3 gap-8">
            {filteredProducts.map(product => (
              <div
                key={product.id}
                className="bg-white rounded-3xl shadow-xl overflow-hidden hover:shadow-2xl transform hover:-translate-y-3 transition-all duration-300 border-4 border-transparent hover:border-yellow-400"
              >
                <div className="relative h-64 bg-gradient-to-br from-blue-50 to-orange-50 overflow-hidden">
                  <img
                    src={product.image}
                    alt={product.name}
                    className="w-full h-full object-cover hover:scale-110 transition-transform duration-500"
                  />
                  <div className="absolute top-4 right-4 bg-blue-600 text-white px-4 py-2 rounded-full text-sm font-bold shadow-lg border-2 border-yellow-400">
                    {product.category}
                  </div>
                </div>

                <div className="p-6">
                  <h3 className="text-xl font-bold text-gray-800 mb-2">{product.name}</h3>
                  <p className="text-gray-600 text-sm mb-4 line-clamp-3">{product.description}</p>

                  <div className="flex items-center justify-center">
                    <div className="text-center">
                      <div className="text-xs text-gray-500 font-semibold mb-1">ONLY</div>
                      <span className="text-4xl font-black text-blue-700">
                        ${product.price.toFixed(2)}
                      </span>
                    </div>
                  </div>
                </div>
              </div>
            ))}
          </div>
        )}
      </main>

      {/* Footer */}
      <footer className="bg-white border-t-4 border-yellow-400 mt-16">
        <div className="max-w-7xl mx-auto px-4 py-8 sm:px-6 lg:px-8">
          <div className="text-center">
            <img 
              src="/images/logo.png" 
              alt="UnrealPrices Logo" 
              className="h-16 w-16 object-contain mx-auto mb-4"
            />
            <p className="text-gray-600 font-medium">UnrealPrices - Amazing Deals, Unbeatable Prices</p>
            <p className="text-gray-400 text-sm mt-2">© 2024 UnrealPrices. All rights reserved.</p>
          </div>
        </div>
      </footer>
    </div>
  );
};

export default AirtableStore;
